import React from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Screen } from '../../types';

/** Optimized WebP art (generated by scripts/optimize-assets.mjs). */
export const SCREEN_BACKGROUNDS: Partial<Record<Screen, string>> = {
    [Screen.Dashboard]: '/assets/bg/home.webp',
    [Screen.Squad]: '/assets/bg/squad.webp',
    [Screen.Transfers]: '/assets/bg/transfers.webp',
    [Screen.League]: '/assets/bg/tournaments.webp',
    [Screen.Trophies]: '/assets/bg/tournaments.webp',
    [Screen.Finances]: '/assets/bg/finances.webp',
    [Screen.Statistics]: '/assets/bg/finances.webp',
    [Screen.Calendar]: '/assets/bg/match.webp',
    [Screen.Club]: '/assets/bg/club.webp',
    [Screen.Stadium]: '/assets/bg/club.webp',
    [Screen.Sponsorships]: '/assets/bg/club.webp',
    [Screen.Staff]: '/assets/bg/squad.webp',
    [Screen.Profile]: '/assets/bg/election.webp',
    [Screen.Settings]: '/assets/bg/home.webp',
};

export const HERO_BANNERS = {
    nextMatch: '/assets/hero/next-match.webp',
    transfers: '/assets/hero/transfers.webp',
    board: '/assets/hero/board.webp',
    club: '/assets/hero/club.webp',
    tournaments: '/assets/hero/tournaments.webp',
    trophies: '/assets/hero/trophies.webp',
} as const;

interface ScreenBackdropProps {
    screen: Screen;
}

/**
 * Fixed, full-viewport atmospheric background that cross-fades between screens.
 * Image sits in the upper area; a strong gradient keeps the content zone dark & legible.
 */
export const ScreenBackdrop: React.FC<ScreenBackdropProps> = ({ screen }) => {
    const src = SCREEN_BACKGROUNDS[screen] ?? SCREEN_BACKGROUNDS[Screen.Dashboard]!;
    return (
        <div aria-hidden className="fixed inset-0 z-0 pointer-events-none overflow-hidden" style={{ background: 'var(--apex-darker)' }}>
            <AnimatePresence initial={false}>
                <motion.div
                    key={src}
                    initial={{ opacity: 0, scale: 1.04 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0 }}
                    transition={{ duration: 0.6, ease: 'easeOut' }}
                    className="absolute inset-0 bg-cover bg-top"
                    style={{ backgroundImage: `url("${src}")` }}
                />
            </AnimatePresence>
            {/* Legibility gradient: show art on top, fade to deep navy below */}
            <div
                className="absolute inset-0"
                style={{
                    background:
                        'linear-gradient(180deg, rgba(4,6,13,0.45) 0%, rgba(4,6,13,0.72) 28%, rgba(5,8,17,0.93) 55%, rgba(4,6,13,0.98) 100%)',
                }}
            />
            {/* Club color ambient glow */}
            <div
                className="absolute -top-32 left-1/2 -translate-x-1/2 w-[140%] h-80 rounded-full blur-3xl opacity-40"
                style={{ background: 'radial-gradient(closest-side, color-mix(in srgb, var(--club-color) 55%, transparent), transparent)' }}
            />
            <div className="apex-grain" />
        </div>
    );
};
